glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 v_color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 v_color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform Constant {
  vec2 center;
  float ratio;
  float  width ;
  float  height ;
  float  round ;
  float  feather;
};
vec4 frag () {
  vec4 color = v_color;
  color *= texture(cc_spriteTexture,uv0);
  float minX = center.x - (width/2.0);
  float maxX = center.x + (width/2.0);
  float minY = center.y - (height * ratio/2.0);
  float maxY = center.y + (height * ratio/2.0);
  if(uv0.x >= minX && uv0.x <= maxX && uv0.y >= minY && uv0.y <= maxY) {
    if(round==0.)discard;
    float roundY = round*ratio;
    vec2 vertex;
    if(uv0.x<=minX+round){
      if(uv0.y<=minY+roundY) {
        vertex = vec2(minX+round,(minY+roundY)/ratio);
      } else if(uv0.y>=maxY-roundY) {
        vertex = vec2(minX+round,(maxY-roundY)/ratio);
      } else {
        vertex = vec2(minX+round,uv0.y/ratio);
      }
    } else if(uv0.x>=maxX-round) {
      if(uv0.y<=minY+roundY) {
        vertex = vec2(maxX-round,(minY+roundY)/ratio);
      } else if(uv0.y>=maxY-roundY) {
        vertex = vec2(maxX-round,(maxY-roundY)/ratio);
      } else{
        vertex = vec2(maxX-round,uv0.y/ratio);
      }
    } else if(uv0.y<=minY+roundY){
      vertex = vec2(uv0.x,(minY+roundY)/ratio);
    } else if(uv0.y>=maxY-roundY){
      vertex = vec2(uv0.x,(maxY-roundY)/ratio);
    } else {
      discard;
    }
    float dis = distance(vec2(uv0.x,uv0.y/ratio),vertex);
    color.a = smoothstep(round-feather,round,dis);
  } else {
    color.a = 1.0;
  }
  color.a *= v_color.a;
  return color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

